package darksafe

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"math"
	"math/big"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf16"
	"unicode/utf8"
)

// Point 是一条序列上某个时间戳的采样值。
type Point struct {
	Timestamp int64   `json:"timestamp"`
	Value     float64 `json:"value"`
}

// SeriesView 是结果输出用的一条序列视图，标签按键升序呈现。
type SeriesView struct {
	Name   string            `json:"name"`
	Labels map[string]string `json:"labels"`
	Points []Point           `json:"points"`
}

// QuerySeries 是查询结果中的一条序列：完整身份与区间内点的个数及算术平均值。
type QuerySeries struct {
	Name    string            `json:"name"`
	Labels  map[string]string `json:"labels"`
	Count   int               `json:"count"`
	Average float64           `json:"average"`
}

// QueryResult 是一次区间均值查询成功后的结果，只读，不改变存储。
type QueryResult struct {
	Status string        `json:"status"`
	Op     string        `json:"op"`
	Series []QuerySeries `json:"series"`
}

// BatchResult 是一批采样点写入成功后的结果。
type BatchResult struct {
	Status     string       `json:"status"`
	Added      int          `json:"added"`
	Duplicates int          `json:"duplicates"`
	Series     []SeriesView `json:"series"`
}

// SeriesRef 标识一条序列：指标名加完整标签集合。
// 缺少某个标签与该标签值为空字符串属于不同序列。
type SeriesRef struct {
	Name   string            `json:"name"`
	Labels map[string]string `json:"labels"`
}

// Conflict 描述同一序列同一时间戳已存在不同的值。
type Conflict struct {
	Series    SeriesRef `json:"series"`
	Timestamp int64     `json:"timestamp"`
	Existing  float64   `json:"existing"`
	Submitted float64   `json:"submitted"`
}

// LineError 是一行（一批）输入失败后的结构化结果。
// Line 由命令入口按从 1 开始的行号填入；Index 为采样点在批次内从 1 开始的位置，
// 整行 JSON 无法解析或不是数组时 Index 为零并省略。
type LineError struct {
	Status   string    `json:"status"`
	Line     int       `json:"line,omitempty"`
	Index    int       `json:"index,omitempty"`
	Error    string    `json:"error"`
	Conflict *Conflict `json:"conflict,omitempty"`
}

// MetricStore 保存一次命令运行期间已写入的指标数据，仅存在于内存中，进程结束即丢弃。
type MetricStore struct {
	series map[seriesID]*storedSeries
}

// seriesID 是序列的规范身份，标签书写顺序不影响身份。
type seriesID struct {
	name string
	// sig 为排序后标签键值对的长度前缀拼接，避免不同写法产生碰撞。
	sig string
}

type storedSeries struct {
	ref    SeriesRef
	points map[int64]float64
}

// NewMetricStore 创建一个空的指标存储。
func NewMetricStore() *MetricStore {
	return &MetricStore{series: make(map[seriesID]*storedSeries)}
}

// cloneLabels 返回标签集合的独立副本；空标签仍复制为非 nil 的空集合，
// 调用方对副本的增删改不影响存储中的序列身份。
func cloneLabels(labels map[string]string) map[string]string {
	out := make(map[string]string, len(labels))
	for k, v := range labels {
		out[k] = v
	}
	return out
}

func sortedKeys(m map[string]string) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

func makeSeriesID(name string, labels map[string]string) seriesID {
	var b strings.Builder
	for _, k := range sortedKeys(labels) {
		v := labels[k]
		fmt.Fprintf(&b, "%d:%s;%d:%s;", len(k), k, len(v), v)
	}
	return seriesID{name: name, sig: b.String()}
}

// labelPair 是标签键值对字典序比较的单元。
type labelPair struct {
	Key, Value string
}

func sortedPairs(labels map[string]string) []labelPair {
	keys := sortedKeys(labels)
	pairs := make([]labelPair, len(keys))
	for i, k := range keys {
		pairs[i] = labelPair{Key: k, Value: labels[k]}
	}
	return pairs
}

func compareLabelPairs(a, b []labelPair) int {
	n := len(a)
	if len(b) < n {
		n = len(b)
	}
	for i := 0; i < n; i++ {
		if a[i].Key != b[i].Key {
			return strings.Compare(a[i].Key, b[i].Key)
		}
		if a[i].Value != b[i].Value {
			return strings.Compare(a[i].Value, b[i].Value)
		}
	}
	switch {
	case len(a) < len(b):
		return -1
	case len(a) > len(b):
		return 1
	}
	return 0
}

var (
	jsonIntegerRE = regexp.MustCompile(`^-?(0|[1-9][0-9]*)$`)
	jsonNumberRE  = regexp.MustCompile(`^-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?$`)
)

// ProcessLine 处理一行非空输入：JSON 数组为写入批次，JSON 对象为查询/操作。
// 成功时返回非 nil 的 *BatchResult 或 *QueryResult 且错误为 nil；任何失败都返回
// 真正的 nil 结果与 *LineError，调用方直接比较 result == nil 即可判定失败，
// 无须先区分结果类型。空写入数组与无命中的查询仍是成功，结果不为 nil。
func (s *MetricStore) ProcessLine(line string) (any, *LineError) {
	top, ok, lerr := decodeTopValue(line)
	if lerr != nil {
		return nil, lerr
	}
	switch ok {
	case '[':
		var items []json.RawMessage
		if err := json.Unmarshal(top, &items); err != nil {
			return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
		}
		// 不能把 *BatchResult 直接装进 any 返回：失败时它是带类型的 nil 指针，
		// 接口值非 nil，调用方会把失败误判为有结果。
		batch, lerr := s.ingestItems(items)
		if lerr != nil {
			return nil, lerr
		}
		return batch, nil
	case '{':
		// 同上：失败时不能把带类型 nil 的 *QueryResult 装进 any。
		query, lerr := s.queryFromObject(top)
		if lerr != nil {
			return nil, lerr
		}
		return query, nil
	default:
		return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
	}
}

// IngestLine 解析并写入一行（一批）采样点。成功返回 BatchResult；
// 失败返回 *LineError，此时此前各批数据保留、本批不写入任何数据。
func (s *MetricStore) IngestLine(line string) (*BatchResult, *LineError) {
	top, ok, lerr := decodeTopValue(line)
	if lerr != nil {
		return nil, lerr
	}
	if ok != '[' {
		return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples"}
	}
	var items []json.RawMessage
	if err := json.Unmarshal(top, &items); err != nil {
		return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
	}
	return s.ingestItems(items)
}

// QueryLine 解析并执行一行查询对象。成功返回 QueryResult；查询只读，不改变存储。
func (s *MetricStore) QueryLine(line string) (*QueryResult, *LineError) {
	top, ok, lerr := decodeTopValue(line)
	if lerr != nil {
		return nil, lerr
	}
	if ok != '{' {
		return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a query object"}
	}
	return s.queryFromObject(top)
}

// validateLineText 在 JSON 解析之前强制整行文本合法：原始字节必须是合法
// UTF-8，字符串内的 Unicode 转义必须表示有效字符。编码层/JSON 解析器会把
// 非法字节或未配对代理项静默替换成 U+FFFD，使损坏文本混入合法序列（被误判为
// 重复、冲突或错误命中查询），因此这里一律拒绝而不是修补后继续。
//
// 逐字节扫描、只在字符串内部识别转义：跳过词法空白与全部非字符串 token。
// 被转义的反斜杠（\\）后的 "uXXXX" 只是普通文本，不会被当成 Unicode 转义。
func validateLineText(line string) *LineError {
	if !utf8.ValidString(line) {
		return &LineError{Status: "error", Error: "invalid JSON: input is not valid UTF-8 text"}
	}
	inString := false
	for i := 0; i < len(line); i++ {
		c := line[i]
		if !inString {
			if c == '"' {
				inString = true
			}
			continue
		}
		switch c {
		case '"':
			inString = false
		case '\\':
			if i+1 >= len(line) {
				break // 悬空反斜杠：交给 JSON 解析器报错
			}
			if line[i+1] != 'u' {
				i++ // 单字符转义（\\、\"、\n 等），跳过被转义字符
				continue
			}
			// i 指向 '\'，i+1 指向 'u'；转义占据 i..i+5。
			r, size := decodeJSONHexEscape(line, i+1)
			if size == 0 {
				return &LineError{Status: "error", Error: "invalid JSON: invalid Unicode escape sequence"}
			}
			if !utf16.IsSurrogate(r) {
				i += 5
				continue
			}
			if r >= 0xDC00 {
				// 单独出现的低代理项。
				return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
			}
			// 高代理项后必须紧接另一个表示低代理项的 \uXXXX 转义。
			loPos := i + 6 // 第一个转义之后的字符位置
			if loPos+1 >= len(line) || line[loPos] != '\\' || line[loPos+1] != 'u' {
				return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
			}
			lo, loSize := decodeJSONHexEscape(line, loPos+1)
			if loSize == 0 || lo < 0xDC00 || lo > 0xDFFF {
				return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
			}
			i = loPos + loSize // 跳到第二转义的最后一个十六进制位，循环自增后越出
		}
	}
	return nil
}

// decodeJSONHexEscape 解析 line[pos:] 处的 "uXXXX"（pos 指向 'u'），
// 返回其码元与占用字节数（固定为 5）；不足四个十六进制数字时 size 为 0。
func decodeJSONHexEscape(line string, pos int) (rune, int) {
	if pos+4 >= len(line) {
		return 0, 0
	}
	var v rune
	for j := pos + 1; j <= pos+4; j++ {
		c := line[j]
		var d rune
		switch {
		case c >= '0' && c <= '9':
			d = rune(c - '0')
		case c >= 'a' && c <= 'f':
			d = rune(c-'a') + 10
		case c >= 'A' && c <= 'F':
			d = rune(c-'A') + 10
		default:
			return 0, 0
		}
		v = v<<4 | d
	}
	return v, 5
}

// decodeTopValue 解析单行中唯一的 JSON 值并返回其原始内容与首个非空白字节
// （'[' 或 '{'）。整个值无法解析、为空或存在尾随内容时返回 *LineError。
func decodeTopValue(line string) (json.RawMessage, byte, *LineError) {
	if lerr := validateLineText(line); lerr != nil {
		return nil, 0, lerr
	}
	dec := json.NewDecoder(strings.NewReader(line))
	var top json.RawMessage
	if err := dec.Decode(&top); err != nil {
		return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
	}
	// 第一个 JSON 值之后只允许输入结束（Decoder 自动跳过尾随空白）。
	if err := dec.Decode(new(json.RawMessage)); err != io.EOF {
		if err == nil {
			err = fmt.Errorf("unexpected content after the JSON value")
		}
		return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
	}
	trimmed := strings.TrimSpace(string(top))
	if len(trimmed) == 0 || (trimmed[0] != '[' && trimmed[0] != '{') {
		return nil, 0, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
	}
	return top, trimmed[0], nil
}

// fieldReader 从 dec 读取并校验当前字段的值，写入调用方持有的结果。
// 采样点与查询对象各自注册自己允许的字段及字段含义。
type fieldReader func(dec *json.Decoder) error

// parseStrictObject 是写入采样点与查询对象共用的严格对象校验骨架：
// 仅允许 fields 中列出的字段（未知字段先于判重被拒绝），同一对象内按转义还原
// 后的字段名判重（即使两个值相同也拒绝；判重不跨对象、不跨层级），按输入次序
// 逐字段调用对应的 fieldReader，对象结束后要求输入恰好耗尽，最后按 required
// 的顺序报告缺失的必填字段。notObjectMsg 与 trailingMsg 由调用方给出，
// 保留各自输入的措辞。
func parseStrictObject(raw json.RawMessage, notObjectMsg, trailingMsg string, required []string, fields map[string]fieldReader) error {
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber()

	tok, err := dec.Token()
	if err != nil {
		return err
	}
	if d, ok := tok.(json.Delim); !ok || d != '{' {
		return fmt.Errorf("%s", notObjectMsg)
	}

	present := make(map[string]bool)
	for dec.More() {
		keyTok, err := dec.Token()
		if err != nil {
			return err
		}
		key := keyTok.(string)
		read, ok := fields[key]
		if !ok {
			return fmt.Errorf("unknown field %q", key)
		}
		if present[key] {
			return fmt.Errorf("duplicate field %q", key)
		}
		present[key] = true
		if err := read(dec); err != nil {
			return err
		}
	}
	if _, err := dec.Token(); err != nil { // 消耗 '}'
		return err
	}
	if _, err := dec.Token(); err != io.EOF {
		if err == nil {
			return fmt.Errorf("%s", trailingMsg)
		}
		return err
	}

	for _, field := range required {
		if !present[field] {
			return fmt.Errorf("missing required field %q", field)
		}
	}
	return nil
}

// readNameField 读取写入与查询共用的指标名字段：必须是非空字符串。
func readNameField(dec *json.Decoder, dst *string) error {
	t, err := dec.Token()
	if err != nil {
		return err
	}
	s, ok := t.(string)
	if !ok {
		return fmt.Errorf(`field "name" must be a string`)
	}
	if s == "" {
		return fmt.Errorf(`field "name" must be a non-empty string`)
	}
	*dst = s
	return nil
}

// readInt64Field 读取 int64 毫秒整数字段（timestamp/start/end）：
// 必须是 JSON 整数且在 int64 范围内，数字字符串、布尔值、带小数点一律拒绝。
func readInt64Field(dec *json.Decoder, field string, dst *int64) error {
	n, err := nextJSONNumber(dec, field)
	if err != nil {
		return err
	}
	v, err := parseJSONInt(n)
	if err != nil {
		return fmt.Errorf("field %q: %s", field, err)
	}
	*dst = v
	return nil
}

// readFiniteFloatField 读取采样值字段：必须是可表示为有限 float64 的 JSON 数字。
func readFiniteFloatField(dec *json.Decoder, field string, dst *float64) error {
	n, err := nextJSONNumber(dec, field)
	if err != nil {
		return err
	}
	v, err := parseFiniteFloat(n)
	if err != nil {
		return fmt.Errorf("field %q: %s", field, err)
	}
	*dst = v
	return nil
}

// readLabelsField 读取标签对象字段并写入 dst；notObjectMsg 保留各输入侧措辞。
func readLabelsField(dec *json.Decoder, notObjectMsg string, dst *map[string]string) error {
	labels, err := parseLabels(dec, notObjectMsg)
	if err != nil {
		return err
	}
	*dst = labels
	return nil
}

type parsedSample struct {
	name   string
	ts     int64
	value  float64
	labels map[string]string
}

// parseSample 对单个采样点做严格校验：仅允许四个已知字段、拒绝重复键，
// 标量必须是精确的 JSON 类型，timestamp 为 int64 整数，value 为有限 float64。
func parseSample(raw json.RawMessage) (parsedSample, error) {
	var p parsedSample
	p.labels = map[string]string{}
	err := parseStrictObject(raw,
		"each sample must be a JSON object",
		"unexpected content after the sample object",
		[]string{"name", "timestamp", "value"},
		map[string]fieldReader{
			"name":      func(dec *json.Decoder) error { return readNameField(dec, &p.name) },
			"timestamp": func(dec *json.Decoder) error { return readInt64Field(dec, "timestamp", &p.ts) },
			"value":     func(dec *json.Decoder) error { return readFiniteFloatField(dec, "value", &p.value) },
			"labels": func(dec *json.Decoder) error {
				return readLabelsField(dec, `field "labels" must be an object of string keys to string values`, &p.labels)
			},
		})
	return p, err
}

// parseLabels 从 dec 读取一个标签对象并做统一校验：必须是 JSON 对象
// （否则返回调用方给出的 notObjectMsg，写入与查询措辞不同），键为非空字符串、
// 值为字符串（空串合法，键值均不做清理），重复键一律拒绝。
// 判重先于值的类型校验：某个键第一次出现时若值不是字符串，仍报告该值的类型
// 错误；而该键再次出现时，无论第二次的值是什么（数字、布尔、null、对象、数组），
// 都先报告重复标签键，不能让第二次值的类型掩盖键重复。
// 返回的集合不含标签时也是非 nil 的空 map，与省略 labels 的语义一致。
func parseLabels(dec *json.Decoder, notObjectMsg string) (map[string]string, error) {
	t, err := dec.Token()
	if err != nil {
		return nil, err
	}
	d, ok := t.(json.Delim)
	if !ok || d != '{' {
		return nil, fmt.Errorf("%s", notObjectMsg)
	}
	labels := map[string]string{}
	for dec.More() {
		labelKeyTok, err := dec.Token()
		if err != nil {
			return nil, err
		}
		labelKey := labelKeyTok.(string)
		if labelKey == "" {
			return nil, fmt.Errorf(`field "labels": label keys must be non-empty strings`)
		}
		// 先判重再读值：与采样点/查询字段的判重一致，重复键不被值的类型掩盖。
		if _, dup := labels[labelKey]; dup {
			return nil, fmt.Errorf(`field "labels": duplicate label key %q`, labelKey)
		}
		valTok, err := dec.Token()
		if err != nil {
			return nil, err
		}
		labelVal, ok := valTok.(string)
		if !ok {
			return nil, fmt.Errorf(`field "labels": value of label %q must be a string`, labelKey)
		}
		labels[labelKey] = labelVal
	}
	if _, err := dec.Token(); err != nil { // 消耗 '}'
		return nil, err
	}
	return labels, nil
}

func nextJSONNumber(dec *json.Decoder, field string) (json.Number, error) {
	t, err := dec.Token()
	if err != nil {
		return "", err
	}
	n, ok := t.(json.Number)
	if !ok {
		return "", fmt.Errorf(`field %q must be a JSON number`, field)
	}
	return n, nil
}

func parseJSONInt(n json.Number) (int64, error) {
	s := string(n)
	if !jsonIntegerRE.MatchString(s) {
		return 0, fmt.Errorf("must be a JSON integer in milliseconds")
	}
	v, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("must be within int64 range")
	}
	return v, nil
}

func parseFiniteFloat(n json.Number) (float64, error) {
	s := string(n)
	if !jsonNumberRE.MatchString(s) {
		return 0, fmt.Errorf("must be a JSON number")
	}
	v, err := strconv.ParseFloat(s, 64)
	if err != nil || math.IsInf(v, 0) || math.IsNaN(v) {
		return 0, fmt.Errorf("must be a finite number representable as float64")
	}
	return v, nil
}

// ingestItems 完成全部采样点校验与冲突检测后再统一提交，保证整批原子性。
func (s *MetricStore) ingestItems(items []json.RawMessage) (*BatchResult, *LineError) {
	type pending struct {
		id  seriesID
		ref SeriesRef
		ts  int64
		val float64
	}

	added := 0
	// 本批已确定身份的点（含与已写入数据重复的点），用于批内去重与冲突检测。
	seen := make(map[seriesID]map[int64]float64)
	// 仅记录需要落盘的新增点；校验全部通过后才提交。
	commits := make([]pending, 0, len(items))

	failAt := func(index int, msg string) *LineError {
		return &LineError{Status: "error", Index: index, Error: msg}
	}
	conflictAt := func(index int, ref SeriesRef, ts int64, existing, submitted float64) *LineError {
		return &LineError{
			Status: "error",
			Index:  index,
			Error: fmt.Sprintf("conflict: series %s at timestamp %d already has value %s, submitted %s",
				ref, ts, formatFloat(existing), formatFloat(submitted)),
			Conflict: &Conflict{
				// 标签必须复制：冲突结果是本次失败的独立记录，
				// 调用方修改它不能改动已存序列的身份。
				Series:    SeriesRef{Name: ref.Name, Labels: cloneLabels(ref.Labels)},
				Timestamp: ts,
				Existing:  existing,
				Submitted: submitted,
			},
		}
	}

	for i, item := range items {
		pos := i + 1
		p, err := parseSample(item)
		if err != nil {
			return nil, failAt(pos, err.Error())
		}

		id := makeSeriesID(p.name, p.labels)
		ref := SeriesRef{Name: p.name, Labels: p.labels}

		if byTS, ok := seen[id]; ok {
			if old, ok := byTS[p.ts]; ok {
				if old != p.value {
					return nil, conflictAt(pos, ref, p.ts, old, p.value)
				}
				// 同批内重复出现且数值相同：重复，成功忽略。
				continue
			}
		}
		if sr, ok := s.series[id]; ok {
			if old, ok := sr.points[p.ts]; ok {
				if old != p.value {
					return nil, conflictAt(pos, sr.ref, p.ts, old, p.value)
				}
				// 与此前批次已写入的值相同：重复，成功忽略。
				if seen[id] == nil {
					seen[id] = map[int64]float64{}
				}
				seen[id][p.ts] = p.value
				continue
			}
		}

		added++
		if seen[id] == nil {
			seen[id] = map[int64]float64{}
		}
		seen[id][p.ts] = p.value
		commits = append(commits, pending{id: id, ref: ref, ts: p.ts, val: p.value})
	}

	// 全部采样点合法且无冲突，原子提交本批新增点。
	for _, c := range commits {
		sr := s.series[c.id]
		if sr == nil {
			sr = &storedSeries{ref: c.ref, points: map[int64]float64{}}
			s.series[c.id] = sr
		}
		sr.points[c.ts] = c.val
	}

	return s.snapshot(added, len(items)-added), nil
}

// formatFloat 以 JSON 数值风格格式化 float64：1 与 1.0 均显示为 1。
func formatFloat(v float64) string {
	return strconv.FormatFloat(v, 'g', -1, 64)
}

type parsedQuery struct {
	name   string
	start  int64
	end    int64
	labels map[string]string
}

// queryFromObject 严格解析查询对象并执行只读区间均值查询。
func (s *MetricStore) queryFromObject(raw json.RawMessage) (*QueryResult, *LineError) {
	q, err := parseQuery(raw)
	if err != nil {
		return nil, &LineError{Status: "error", Error: err.Error()}
	}
	if q.start > q.end {
		return nil, &LineError{Status: "error", Error: fmt.Sprintf(
			`invalid range: "start" must not be greater than "end" (%d > %d)`, q.start, q.end)}
	}
	return s.runQuery(q), nil
}

// parseQuery 对查询对象做严格校验：仅允许 op/name/start/end/labels，
// 拒绝重复键与未知字段；标量必须是精确的 JSON 类型，start/end 为 int64 毫秒。
func parseQuery(raw json.RawMessage) (parsedQuery, error) {
	var q parsedQuery
	err := parseStrictObject(raw,
		"each query must be a JSON object",
		"unexpected content after the query object",
		[]string{"op", "name", "start", "end"},
		map[string]fieldReader{
			"op": func(dec *json.Decoder) error {
				t, err := dec.Token()
				if err != nil {
					return err
				}
				op, ok := t.(string)
				if !ok {
					return fmt.Errorf(`field "op" must be a string`)
				}
				if op != "query" {
					return fmt.Errorf(`unknown op %q (only "query" is supported)`, op)
				}
				return nil
			},
			"name":  func(dec *json.Decoder) error { return readNameField(dec, &q.name) },
			"start": func(dec *json.Decoder) error { return readInt64Field(dec, "start", &q.start) },
			"end":   func(dec *json.Decoder) error { return readInt64Field(dec, "end", &q.end) },
			"labels": func(dec *json.Decoder) error {
				return readLabelsField(dec, `field "labels" must be an object of non-empty string keys to string values`, &q.labels)
			},
		})
	return q, err
}

// labelsMatch 实现子集匹配：want 中每个键都必须在 stored 中存在且值完全相等，
// stored 可以含额外标签；空字符串值只匹配真实存在的空值标签。
func labelsMatch(want, stored map[string]string) bool {
	for k, v := range want {
		got, ok := stored[k]
		if !ok || got != v {
			return false
		}
	}
	return true
}

// runQuery 只读扫描已成功提交的数据：name 精确、标签子集、[start,end] 闭区间。
// 序列次序与写入快照共用 organizeSeries 的整理结果：过滤掉其他序列后，
// 保留的序列仍是同一排序中的一个子序列，不另换排序；无区间内点的序列不列出。
func (s *MetricStore) runQuery(q parsedQuery) *QueryResult {
	inRange := func(ts int64) bool { return ts >= q.start && ts <= q.end }
	out := make([]QuerySeries, 0)
	for _, os := range s.organizeSeries() {
		if os.ref.Name != q.name || !labelsMatch(q.labels, os.ref.Labels) {
			continue
		}
		points := sortedSeriesPoints(os.sr, inRange)
		if len(points) == 0 {
			continue
		}
		values := make([]float64, len(points))
		for i, p := range points {
			values[i] = p.Value
		}
		out = append(out, QuerySeries{
			Name:    os.ref.Name,
			Labels:  os.ref.Labels,
			Count:   len(values),
			Average: finiteMean(values),
		})
	}
	return &QueryResult{Status: "ok", Op: "query", Series: out}
}

// finiteMean 返回已存储 float64 值的精确算术平均所对应的最近 float64，
// 恰好在两个相邻可表示值中间时按最近偶数舍入。
// 求和用有理数精确完成：与点的顺序、批次划分无关，正负大数抵消后的小余量
// 不会丢失，总和超出 float64 范围时结果仍然有限。精确平均为零时返回 +0；
// 只有一个点时结果就是该点的值。
func finiteMean(values []float64) float64 {
	sum := new(big.Rat)
	r := new(big.Rat)
	for _, v := range values {
		// 写入侧已保证 v 有限，SetFloat64 对有限值是精确的。
		sum.Add(sum, r.SetFloat64(v))
	}
	sum.Quo(sum, r.SetInt64(int64(len(values))))
	return ratToFloat64NearestEven(sum)
}

// ratToFloat64NearestEven 把有理数 x 舍入到最近的 float64，半数取偶。
// 调用方保证 |x| 不超过 MaxFloat64（有限值的均值必然满足），因此不会溢出。
func ratToFloat64NearestEven(x *big.Rat) float64 {
	if x.Sign() == 0 {
		return 0
	}
	num := new(big.Int).Set(x.Num())
	den := x.Denom()
	neg := num.Sign() < 0
	if neg {
		num.Neg(num)
	}

	// e 满足 2^e <= num/den < 2^(e+1)。
	e := floorLog2Rat(num, den)
	var m *big.Int
	scale := 0
	if e >= -1022 {
		// 正规数：m 为 num/den 按 2^(e-52) 缩放后的 53 位舍入整数。
		scale = e - 52
		m = roundScaledRatio(num, den, scale)
		if m.BitLen() == 54 {
			// 舍入进位（如 1.111…1 进为 10.0），指数加一。
			m.Rsh(m, 1)
			scale++
		}
	} else {
		// 次正规数：有效位间距固定为 2^-1074；m 舍入为 0 时按 IEEE 得到带符号零。
		scale = -1074
		m = roundScaledRatio(num, den, scale)
	}
	// m < 2^53，可以精确放入 int64 与 float64。
	f := math.Ldexp(float64(m.Int64()), scale)
	if neg {
		return -f
	}
	return f
}

// floorLog2Rat 返回正有理数 num/den 的二进制阶：最大的 e 使 2^e <= num/den。
func floorLog2Rat(num, den *big.Int) int {
	k := num.BitLen() - den.BitLen()
	var t big.Int
	if k >= 0 {
		t.Lsh(den, uint(k))
		if num.Cmp(&t) >= 0 {
			return k
		}
		return k - 1
	}
	t.Lsh(num, uint(-k))
	if t.Cmp(den) >= 0 {
		return k
	}
	return k - 1
}

// roundScaledRatio 返回 round(num / (den · 2^scale))，半数取偶；num、den 均为正。
func roundScaledRatio(num, den *big.Int, scale int) *big.Int {
	n := new(big.Int).Set(num)
	d := new(big.Int).Set(den)
	if scale >= 0 {
		d.Lsh(d, uint(scale))
	} else {
		n.Lsh(n, uint(-scale))
	}
	q, r := new(big.Int).QuoRem(n, d, new(big.Int))
	switch r2 := new(big.Int).Lsh(r, 1); r2.Cmp(d) {
	case 1:
		q.Add(q, big.NewInt(1))
	case 0:
		if q.Bit(0) == 1 {
			q.Add(q, big.NewInt(1))
		}
	}
	return q
}

// String 让冲突原因中的序列身份可读且无歧义：name{k=v,...}，标签按键排序。
// 名称、标签键、标签值是不含分隔字符（逗号、等号、花括号、引号、反斜杠）、
// 不含首尾空白与不可打印字符的非空字符串时按原文呈现（cpu{host=a} 保持原样）；
// 否则以带引号的字符串字面量呈现，使内容字符与标签边界永远可以区分——
// 单标签值 "1,b=2" 渲染为 a="1,b=2"，与两标签 a=1,b=2 不再混淆；换行、
// 制表符等呈现为 \n、\t 这样的可辨认文字标记，一条冲突原因始终是一条记录；
// 空字符串值渲染为 ""，与无标签的 {} 明确区分。渲染只依赖解析后的真实身份，
// 与标签书写顺序、字符是否以 JSON 转义书写无关。
func (r SeriesRef) String() string {
	var b strings.Builder
	b.WriteString(identityText(r.Name))
	b.WriteByte('{')
	for i, p := range sortedPairs(r.Labels) {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(identityText(p.Key))
		b.WriteByte('=')
		b.WriteString(identityText(p.Value))
	}
	b.WriteByte('}')
	return b.String()
}

// identityText 把身份组成部分（指标名、标签键、标签值）渲染为无歧义文本：
// 不含分隔字符、首尾空白与不可打印字符的非空字符串原样返回；其余情况用
// strconv.Quote 加引号并转义，引号边界标出内容的起止（首尾空格、空串可见），
// 控制字符呈现为 \n、\t 等转义标记。分隔字符与引号、反斜杠一律被引号包裹，
// 因此渲染结果不会把内容字符误读为标签边界。
func identityText(s string) string {
	if s == "" || s != strings.TrimSpace(s) {
		return strconv.Quote(s)
	}
	for _, r := range s {
		if !unicode.IsPrint(r) || strings.ContainsRune(`,={}"\`, r) {
			return strconv.Quote(s)
		}
	}
	return s
}

// organizedSeries 是一次结果整理中的一条序列：携带已存序列指针、
// 供结果直接使用的独立标签副本（标签书写顺序不影响身份，
// 副本使调用方对结果的修改不能回写存储），以及该副本按键升序
// 整理好的键值对，供排序比较直接复用。
type organizedSeries struct {
	sr    *storedSeries
	ref   SeriesRef
	pairs []labelPair
}

// organizeSeries 是写入快照与区间查询共用的数据整理逻辑：
// 遍历全部已提交序列，复制各自的序列身份，并按唯一的顺序约定排列——
// 先按指标名字符串字典序，再按标签键升序后的键值对逐对比较
// （先比键再比值，前一对相同才比下一对；较短集合是完整前缀时排前，
// 无标签序列因此排在最前）。标签值按字符串比较（"10" 在 "2" 之前）。
// 每条序列的标签只在遍历时整理一次：排序后的键值对随条目保留，
// sort 的反复比较直接复用同一份结果，不会因一条序列参与多次比较
// 而反复整理同一套标签。整理结果不复制采样点；采样点的选取与升序
// 排列由 sortedSeriesPoints 完成。
func (s *MetricStore) organizeSeries() []organizedSeries {
	out := make([]organizedSeries, 0, len(s.series))
	for _, sr := range s.series {
		// 标签必须复制：成功结果是当次操作的独立记录，
		// 调用方修改结果标签不能改动已存序列的身份。
		labels := cloneLabels(sr.ref.Labels)
		out = append(out, organizedSeries{
			sr:    sr,
			ref:   SeriesRef{Name: sr.ref.Name, Labels: labels},
			pairs: sortedPairs(labels),
		})
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].ref.Name != out[j].ref.Name {
			return out[i].ref.Name < out[j].ref.Name
		}
		return compareLabelPairs(out[i].pairs, out[j].pairs) < 0
	})
	return out
}

// sortedSeriesPoints 按 timestamp 升序返回一条已存序列中满足 keep 的采样点，
// 数值与时间戳一一对应。keep 为 nil 时返回全部点（写入快照）；
// 区间查询传入闭区间判定，查询只选取区间内的点。
// 返回的是新建切片与新建 Point，调用方对采样点的修改不影响存储，
// 也不影响此前或此后取得的其他成功结果。
func sortedSeriesPoints(sr *storedSeries, keep func(ts int64) bool) []Point {
	tsList := make([]int64, 0, len(sr.points))
	for ts := range sr.points {
		if keep == nil || keep(ts) {
			tsList = append(tsList, ts)
		}
	}
	sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
	points := make([]Point, len(tsList))
	for i, ts := range tsList {
		points[i] = Point{Timestamp: ts, Value: sr.points[ts]}
	}
	return points
}

// snapshot 生成按规范排序的全部序列视图：序列次序与点排列均来自
// organizeSeries/sortedSeriesPoints 这套与查询共用的整理逻辑。
func (s *MetricStore) snapshot(added, duplicates int) *BatchResult {
	organized := s.organizeSeries()
	views := make([]SeriesView, 0, len(organized))
	for _, os := range organized {
		views = append(views, SeriesView{
			Name:   os.ref.Name,
			Labels: os.ref.Labels,
			Points: sortedSeriesPoints(os.sr, nil),
		})
	}
	return &BatchResult{Status: "ok", Added: added, Duplicates: duplicates, Series: views}
}

package darksafe

import (
	"strings"
	"testing"
)

// 本文件回归保障“同一条查询请求包含多个问题时”的错误选择规则，使用户能依据
// 返回的错误原因逐步修正输入、再看到剩余的问题（与写入侧的
// batch_error_selection_test.go 对应，覆盖查询对象）：
//
//   - 整条输入必须先能解析为唯一的完整 JSON 值：查询对象未闭合、对象之后
//     还有第二个值或非空白内容时，即使前面的字段已有类型错误，也只报整行
//     解析失败，不能把前面的字段问题当作最终原因。
//   - 结构完整的查询对象按字段原始书写顺序定原因：未知字段与字段类型错误
//     同时存在时先出现者获选，交换位置后原因随之改变。
//   - 首次值合法的已知字段再次出现一律报重复字段，即使第二次的值类型错误；
//     直接书写与转义后还原成同名（如 name）同样算重复。
//   - 缺少必填字段只在已出现字段都通过校验后报告；多个必填字段同时缺失时
//     按 op、name、start、end 的顺序选择，不受其他合法字段排列影响。
//   - start > end 的区间错误在字段校验与必填检查全部通过后才报告：同一请求
//     既有倒置区间又有字段问题时先指出字段问题，修正后再指出区间问题。
//   - 所有查询失败只返回错误：不返回查询结果，不带 index 与 conflict；
//     失败查询不改变存储，此前写入的数据在后续合法查询中原样可见。

// assertQueryError 校验查询级失败：无 index、无 conflict，原因包含 want 子串，
// 使不同的失败类别（未知字段、类型错误、重复字段、缺字段、区间倒置）可区分。
func assertQueryError(t *testing.T, lerr *LineError, want string) {
	t.Helper()
	if lerr == nil {
		t.Fatalf("expected query failure, got success")
	}
	if lerr.Index != 0 {
		t.Fatalf("query failure must not carry index, got index=%d (error: %s)", lerr.Index, lerr.Error)
	}
	if lerr.Conflict != nil {
		t.Fatalf("query failure must not carry a conflict, got %+v", lerr.Conflict)
	}
	if !strings.Contains(lerr.Error, want) {
		t.Fatalf("error = %q, want substring %q", lerr.Error, want)
	}
}

// 查询对象未闭合、对象之后还有第二个 JSON 值或非空白内容时，即使前面的字段
// 已经带类型错误或未知字段，也必须报整行解析失败（无 index、无 conflict），
// 而不是把前面的字段问题当作最终原因。
func TestQueryWholeLineParseErrorBeatsEarlierFieldErrors(t *testing.T) {
	lines := []struct {
		name string
		line string
		want string
	}{
		// 对象未闭合：name 已有类型错误，但整行无法解析。
		{"truncated object", `{"op":"query","name":7,"start":0`, "invalid JSON"},
		// 对象未闭合：未知字段已出现，但整行无法解析。
		{"truncated after unknown field", `{"op":"query","bogus":1,"name":"m"`, "invalid JSON"},
		// 对象之后跟着第二个 JSON 值：对象内 name 已有类型错误。
		{"second JSON value", `{"op":"query","name":7,"start":0,"end":1} {"op":"query"}`, "invalid JSON"},
		// 对象之后跟着第二个 JSON 值：对象内有未知字段。
		{"second value after unknown field", `{"op":"query","bogus":1,"name":"m","start":0,"end":1} []`, "invalid JSON"},
		// 对象之后跟着非空白垃圾：对象内 start 已有类型错误。
		{"trailing garbage", `{"op":"query","name":"m","start":"x","end":1} oops`, "invalid JSON"},
	}
	for _, tc := range lines {
		t.Run(tc.name, func(t *testing.T) {
			store := NewMetricStore()
			// 先写入基线数据，整行失败后必须原样保留、仍可查询。
			mustOK(t, store, `[{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}}]`)

			lerr := mustQueryFail(t, store, tc.line)
			assertWholeLineTextError(t, lerr, tc.want)

			res := mustQuery(t, store, `{"op":"query","name":"cpu","start":0,"end":2000,"labels":{"host":"a"}}`)
			if len(res.Series) != 1 || res.Series[0].Count != 1 || res.Series[0].Average != 2 {
				t.Fatalf("baseline data changed after whole-line failure: %+v", res.Series)
			}
		})
	}
}

// 结构完整的查询对象中，已出现的字段按原始书写顺序决定先报告哪个问题：
// 未知字段与字段类型错误同时存在时先出现者获选；只交换这两个字段的位置，
// 错误原因随之改变。
func TestQueryFieldErrorReasonFollowsInputOrder(t *testing.T) {
	cases := []struct {
		name string
		line string
		want string
	}{
		// 未知字段在前、name 类型错误在后 → 报告未知字段。
		{"unknown field first",
			`{"op":"query","bogus":1,"name":7,"start":0,"end":1}`, `unknown field "bogus"`},
		// name 类型错误在前、未知字段在后 → 报告 name 的类型错误。
		{"type error first",
			`{"op":"query","name":7,"bogus":1,"start":0,"end":1}`, `"name" must be a string`},
		// start 类型错误在前、未知字段在后 → 报告 start 的类型错误。
		{"start type error first",
			`{"op":"query","name":"m","start":"x","bogus":1,"end":1}`, `"start" must be a JSON number`},
		// 未知字段在前、start 类型错误在后 → 报告未知字段。
		{"unknown before start type error",
			`{"op":"query","name":"m","bogus":1,"start":"x","end":1}`, `unknown field "bogus"`},
		// labels 类型错误在前、未知字段在后 → 报告 labels 的类型错误。
		{"labels type error first",
			`{"op":"query","name":"m","start":0,"end":1,"labels":[],"bogus":1}`, `"labels" must be an object`},
		// 未知字段在 labels 类型错误之前 → 报告未知字段。
		{"unknown before labels type error",
			`{"op":"query","name":"m","start":0,"end":1,"bogus":1,"labels":[]}`, `unknown field "bogus"`},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			store := NewMetricStore()
			lerr := mustQueryFail(t, store, tc.line)
			assertQueryError(t, lerr, tc.want)
		})
	}
}

// 首次值合法的已知字段再次出现时一律报告重复字段，即使第二次的值类型也
// 不合法；字段名直接书写与用 \uXXXX 转义还原成同名同样算重复，原因指出
// 还原后的字段名。
func TestQueryDuplicateFieldBeatsSecondValueTypeError(t *testing.T) {
	cases := []struct {
		name string
		line string
		want string // 还原后的字段名
	}{
		// 第二次出现的 start 是字符串（类型也不合法）：仍报重复字段。
		{"literal duplicate, bad second value",
			`{"op":"query","name":"m","start":0,"start":"x","end":1}`, `"start"`},
		// 直接书写 name 后，再把首字母 n 用十六进制转义写一次且值是数字：报重复字段 name。
		{"escaped duplicate, bad second value",
			`{"op":"query","name":"m","\u006eame":7,"start":0,"end":1}`, `"name"`},
		// 转义形式在前（值合法），直接书写在后（值类型错误）：仍报重复字段 name。
		{"escaped first, bad literal second",
			`{"op":"query","\u006eame":"m","name":7,"start":0,"end":1}`, `"name"`},
		// op 第二次出现是数字：报重复字段 op。
		{"duplicate op, bad second value",
			`{"op":"query","op":7,"name":"m","start":0,"end":1}`, `"op"`},
		// end 以转义形式重复出现且值是布尔：报重复字段 end。
		{"escaped duplicate end, bad second value",
			`{"op":"query","name":"m","start":0,"end":1,"\u0065nd":true}`, `"end"`},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			store := NewMetricStore()
			lerr := mustQueryFail(t, store, tc.line)
			assertQueryError(t, lerr, "duplicate field")
			assertQueryError(t, lerr, tc.want)
		})
	}
}

// 缺少必填字段的错误只有在已出现字段都通过校验后才返回：缺 name 同时带
// 未知字段、类型错误或重复字段时，先报告后者；修正已出现字段的问题后，
// 同一输入才报告缺少的必填字段。
func TestQueryMissingRequiredReportedOnlyAfterPresentFieldsValid(t *testing.T) {
	store := NewMetricStore()

	// 缺 name 且带未知字段：先报未知字段。
	lerr := mustQueryFail(t, store, `{"op":"query","start":0,"end":1,"bogus":1}`)
	assertQueryError(t, lerr, `unknown field "bogus"`)

	// 去掉未知字段后，同一输入才报告缺少 name。
	lerr = mustQueryFail(t, store, `{"op":"query","start":0,"end":1}`)
	assertQueryError(t, lerr, `missing required field "name"`)

	// 缺 name 且 start 类型错误：先报类型错误。
	lerr = mustQueryFail(t, store, `{"op":"query","start":"x","end":1}`)
	assertQueryError(t, lerr, `"start" must be a JSON number`)

	// 缺 name 且 start 重复出现：先报重复字段。
	lerr = mustQueryFail(t, store, `{"op":"query","start":0,"start":1,"end":2}`)
	assertQueryError(t, lerr, `duplicate field "start"`)

	// 缺 op 且 name 类型错误：先报类型错误，修正后才报缺 op。
	lerr = mustQueryFail(t, store, `{"name":7,"start":0,"end":1}`)
	assertQueryError(t, lerr, `"name" must be a string`)
	lerr = mustQueryFail(t, store, `{"name":"m","start":0,"end":1}`)
	assertQueryError(t, lerr, `missing required field "op"`)
}

// 多个必填字段同时缺失时，依次按 op、name、start、end 选择第一个缺失项，
// 不受其他合法字段（labels）及其排列位置影响。
func TestQueryMissingRequiredPriorityOrder(t *testing.T) {
	cases := []struct {
		line string
		want string
	}{
		// 四个必填字段全缺：报 op。
		{`{}`, `"op"`},
		{`{"labels":{}}`, `"op"`},
		// 缺 op 与 name：报 op（start/end 排列不影响）。
		{`{"start":0,"end":1}`, `"op"`},
		{`{"end":1,"start":0,"labels":{"host":"a"}}`, `"op"`},
		// 缺 name 与 start：报 name。
		{`{"op":"query","end":1}`, `"name"`},
		{`{"op":"query","end":1,"labels":{}}`, `"name"`},
		// 缺 start 与 end：报 start。
		{`{"op":"query","name":"m"}`, `"start"`},
		{`{"op":"query","name":"m","labels":{"host":"a"}}`, `"start"`},
		// 只缺 start：报 start。
		{`{"op":"query","name":"m","end":1}`, `"start"`},
		// 只缺 end，labels 穿插其间：仍报 end。
		{`{"op":"query","labels":{},"name":"m","start":0}`, `"end"`},
	}
	for _, tc := range cases {
		store := NewMetricStore()
		lerr := mustQueryFail(t, store, tc.line)
		assertQueryError(t, lerr, "missing required field")
		assertQueryError(t, lerr, tc.want)
	}
}

// start > end 的区间错误在字段校验与必填检查全部通过后才返回：同一请求既有
// 倒置区间又有字段问题时先指出字段问题；修正字段问题后，同一请求才指出区间
// 问题，且区间错误同时给出 start 与 end 的实际取值。
func TestQueryRangeErrorReportedOnlyAfterFieldsValid(t *testing.T) {
	store := NewMetricStore()

	// 倒置区间 + 未知字段：先报未知字段。
	lerr := mustQueryFail(t, store, `{"op":"query","name":"m","start":5,"end":1,"extra":1}`)
	assertQueryError(t, lerr, `unknown field "extra"`)

	// 倒置区间 + 缺 end 字段不可能倒置，这里缺 name：先报缺 name。
	lerr = mustQueryFail(t, store, `{"op":"query","start":5,"end":1}`)
	assertQueryError(t, lerr, `missing required field "name"`)

	// 倒置区间 + start 类型错误：先报类型错误。
	lerr = mustQueryFail(t, store, `{"op":"query","name":"m","start":"5","end":1}`)
	assertQueryError(t, lerr, `"start" must be a JSON number`)

	// 倒置区间 + 重复字段：先报重复字段。
	lerr = mustQueryFail(t, store, `{"op":"query","name":"m","start":5,"end":1,"end":2}`)
	assertQueryError(t, lerr, `duplicate field "end"`)

	// 字段全部合法后，同一倒置区间才报告区间错误，并指出 start 与 end 的值。
	lerr = mustQueryFail(t, store, `{"op":"query","name":"m","start":5,"end":1}`)
	assertQueryError(t, lerr, "invalid range")
	assertQueryError(t, lerr, `"start"`)
	assertQueryError(t, lerr, `"end"`)
	assertQueryError(t, lerr, "5 > 1")
}

// 所有查询失败都只返回错误：不返回查询结果，不带 index 与 conflict；
// 先写入一条包含多个时间戳的序列，各类失败查询之后再用合法查询读取相同
// 范围，完整标签、点数和平均值应与失败前一致。
func TestQueryFailuresReturnNoResultAndPreserveData(t *testing.T) {
	store := NewMetricStore()
	mustOK(t, store, `[
		{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a","zone":"z1"}},
		{"name":"cpu","timestamp":2000,"value":4,"labels":{"host":"a","zone":"z1"}},
		{"name":"cpu","timestamp":3000,"value":6,"labels":{"host":"a","zone":"z1"}}
	]`)

	queryLine := `{"op":"query","name":"cpu","start":0,"end":4000,"labels":{"host":"a"}}`
	assertBaseline := func() {
		t.Helper()
		res := mustQuery(t, store, queryLine)
		if len(res.Series) != 1 {
			t.Fatalf("series = %+v, want exactly one", res.Series)
		}
		s0 := res.Series[0]
		if s0.Name != "cpu" || len(s0.Labels) != 2 || s0.Labels["host"] != "a" || s0.Labels["zone"] != "z1" {
			t.Fatalf("series identity = %+v, want cpu{host=a,zone=z1}", s0)
		}
		if s0.Count != 3 || s0.Average != 4 {
			t.Fatalf("series = %+v, want count=3 average=4", s0)
		}
	}
	assertBaseline()

	// 覆盖本文件各类失败：整行解析、未知字段、类型错误、重复字段、
	// 缺必填字段、区间倒置。每一个都只返回错误，不改变存储。
	failures := []struct {
		line string
		want string
	}{
		{`{"op":"query","name":7,"start":0`, "invalid JSON"},
		{`{"op":"query","name":"cpu","start":0,"end":4000} {"op":"query"}`, "invalid JSON"},
		{`{"op":"query","bogus":1,"name":"cpu","start":0,"end":4000}`, `unknown field "bogus"`},
		{`{"op":"query","name":"cpu","start":"x","end":4000}`, `"start" must be a JSON number`},
		{`{"op":"query","name":"cpu","start":0,"start":1,"end":4000}`, `duplicate field "start"`},
		{`{"op":"query","name":"cpu","start":0}`, `missing required field "end"`},
		{`{"op":"query","name":"cpu","start":4000,"end":0}`, "invalid range"},
	}
	for _, f := range failures {
		lerr := mustQueryFail(t, store, f.line)
		assertQueryError(t, lerr, f.want)
	}

	// 失败查询之后，相同范围的合法查询结果与失败前完全一致。
	assertBaseline()
}

// Command darksafe is the 零信任身份与授权决策平台 entry point.
package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/asdhoaiqqq/darksafe-access/darksafe"
)

// maxIngestLineBytes 是 ingest 单行内容的原始字节上限：64 MiB。
// 行分隔符 '\n' 不计入；内容恰好达到上限仍可进入写入或查询处理，只有超过才失败。
const maxIngestLineBytes = 64 * 1024 * 1024 // 67,108,864

func main() {
	command := "demo"
	if len(os.Args) > 1 {
		command = os.Args[1]
	}
	switch command {
	case "demo":
		runDemo()
	case "ingest":
		os.Exit(runIngest(os.Stdin, os.Stdout))
	case "version":
		fmt.Println("darksafe 0.1.0")
	case "help", "-h", "--help":
		usage(os.Stdout)
	default:
		fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
		usage(os.Stderr)
		os.Exit(2)
	}
}

func usage(w io.Writer) {
	fmt.Fprintln(w, "usage: darksafe [demo|version|ingest|help]")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "commands:")
	fmt.Fprintln(w, "  demo     run the bundled access-decision demo")
	fmt.Fprintln(w, "  version  print the version")
	fmt.Fprintln(w, "  ingest   batch-ingest metric samples from standard input")
	fmt.Fprintln(w, "  help     show this help")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "ingest input:")
	fmt.Fprintln(w, "  Standard input is read line by line. Writes and queries may alternate;")
	fmt.Fprintln(w, "  queries only read data committed by earlier successful write lines and")
	fmt.Fprintln(w, "  never change storage. Blank lines produce no result but still count toward")
	fmt.Fprintln(w, "  line numbers. Accepted data is held in memory for this process only and is")
	fmt.Fprintln(w, "  never written to disk. A single line may contain at most 67,108,864 raw")
	fmt.Fprintln(w, "  bytes (64 MiB); the line separator is not counted, so a line of exactly")
	fmt.Fprintln(w, "  that length is still processed. A longer line always fails as one whole")
	fmt.Fprintln(w, "  line: it is never split into multiple inputs and even a valid JSON prefix")
	fmt.Fprintln(w, "  is never treated as a complete request, so it writes no points and runs no")
	fmt.Fprintln(w, "  query. It still produces one error result, data committed by earlier lines")
	fmt.Fprintln(w, "  is retained, and later lines continue to be processed in input order.")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "  Write line: a JSON array of sample objects; each line is one batch.")
	fmt.Fprintln(w, "  A sample is {\"name\": string, \"timestamp\": <int64 milliseconds>,")
	fmt.Fprintln(w, "  \"value\": <finite number>} and may optionally include")
	fmt.Fprintln(w, "  \"labels\": {\"key\": \"value\"}. Empty label values are preserved verbatim;")
	fmt.Fprintln(w, "  omitting labels and passing an empty labels object both mean no labels.")
	fmt.Fprintln(w, "  Missing fields, wrong types, unknown fields, duplicate keys, illegal")
	fmt.Fprintln(w, "  numbers, or input that is not a JSON array fail the whole batch.")
	fmt.Fprintln(w, "  Duplicate keys are compared after JSON unescaping, so a field written")
	fmt.Fprintln(w, "  literally and the same field written with its first letter as a")
	fmt.Fprintln(w, "  \\uXXXX escape collide even when both values are identical; the same")
	fmt.Fprintln(w, "  rule applies to label keys and to query objects. The check is scoped to")
	fmt.Fprintln(w, "  a single object: fields in different samples, and a sample field sharing")
	fmt.Fprintln(w, "  a name with one of its own label keys, are both legal. A write failure")
	fmt.Fprintln(w, "  names the offending sample via its 1-based index and never carries a")
	fmt.Fprintln(w, "  conflict; a query failure carries neither index nor conflict.")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "  Every string (metric names, label keys and label values, in both write")
	fmt.Fprintln(w, "  arrays and query objects) must be valid text: the raw bytes must be valid")
	fmt.Fprintln(w, "  UTF-8, and a \\uXXXX Unicode escape must denote a real character. A lone")
	fmt.Fprintln(w, "  high surrogate, a lone low surrogate, or a high surrogate not followed")
	fmt.Fprintln(w, "  immediately by a valid low surrogate is rejected; it is never repaired into")
	fmt.Fprintln(w, "  U+FFFD. (A backslash-escaped as \\\\uD800 is ordinary text, not an escape.)")
	fmt.Fprintln(w, "  Chinese text, supplementary-plane characters written literally or as a")
	fmt.Fprintln(w, "  matched surrogate pair, and a deliberately typed U+FFFD or \\uFFFD are all")
	fmt.Fprintln(w, "  valid. Corrupt text fails the whole line as a parse error with no index and")
	fmt.Fprintln(w, "  no conflict even if earlier samples in the array were valid: no point from")
	fmt.Fprintln(w, "  that line is committed and a corrupt query returns no matches. The error")
	fmt.Fprintln(w, "  distinguishes invalid UTF-8 bytes from invalid surrogate escapes.")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "  A series is identified by metric name plus its full label set; label order does")
	fmt.Fprintln(w, "  not matter. Submitting the same series/timestamp with the same value is a")
	fmt.Fprintln(w, "  duplicate (1 and 1.0 are equal) and is ignored; a different value rejects the")
	fmt.Fprintln(w, "  entire batch without overwriting anything. Any failure in a batch discards all")
	fmt.Fprintln(w, "  new points from that line; earlier successful batches remain in effect.")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "  Query line: a JSON object {\"op\":\"query\",\"name\":\"cpu\",")
	fmt.Fprintln(w, "  \"start\":1000,\"end\":2000,\"labels\":{\"host\":\"a\"}}. op, name, start and")
	fmt.Fprintln(w, "  end are required; name is an exact, non-empty metric-name match and start/end")
	fmt.Fprintln(w, "  are inclusive int64 millisecond bounds (start == end queries that one")
	fmt.Fprintln(w, "  timestamp; start > end is rejected). labels is optional: omit it or pass {}")
	fmt.Fprintln(w, "  to match every series of the metric; otherwise every given key must exist with")
	fmt.Fprintln(w, "  exactly the same value (extra series labels are allowed, and an empty string")
	fmt.Fprintln(w, "  only matches a label that actually exists with that empty value). Names and")
	fmt.Fprintln(w, "  labels are matched verbatim without trimming or case folding.")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "ingest output (one JSON line per non-empty input line, in input order):")
	fmt.Fprintln(w, "  write ok: {\"status\":\"ok\",\"added\":N,\"duplicates\":N,\"series\":[...]}")
	fmt.Fprintln(w, "           where every known series is listed with name, labels and timestamp-")
	fmt.Fprintln(w, "           sorted points; series are ordered by name and then by sorted labels.")
	fmt.Fprintln(w, "  query ok: {\"status\":\"ok\",\"op\":\"query\",\"series\":[{\"name\":...,")
	fmt.Fprintln(w, "           \"labels\":{},\"count\":N,\"average\":N.N}]} — one entry per series")
	fmt.Fprintln(w, "           having points in range, in the same series order, with the full name")
	fmt.Fprintln(w, "           and label set; an empty match yields []. The arithmetic mean is taken")
	fmt.Fprintln(w, "           over stored float64 values and is always finite for finite inputs.")
	fmt.Fprintln(w, "  failure: {\"status\":\"error\",\"line\":N,\"index\":M,\"error\":\"...\",")
	fmt.Fprintln(w, "           \"conflict\":{...}} — index is the 1-based sample position and is")
	fmt.Fprintln(w, "           omitted when the whole line cannot be parsed or for query lines;")
	fmt.Fprintln(w, "           conflict reports the series, timestamp, existing and submitted values.")
	fmt.Fprintln(w, "           In the error text the series is rendered as name{k=v,...} with labels")
	fmt.Fprintln(w, "           sorted by key; a name, key or value containing commas, equals signs,")
	fmt.Fprintln(w, "           braces, quotes, backslashes, leading/trailing spaces or control")
	fmt.Fprintln(w, "           characters (or an empty string) is shown as a quoted string literal")
	fmt.Fprintln(w, "           (newlines as \\n, tabs as \\t), so content characters are never")
	fmt.Fprintln(w, "           mistaken for label boundaries and one reason stays one record.")
	fmt.Fprintln(w, "           An over-long line reports the size limit as a whole-line error with")
	fmt.Fprintln(w, "           no index and no conflict.")
	fmt.Fprintln(w)
	fmt.Fprintln(w, "  Processing continues after a failed line. The command exits non-zero if any")
	fmt.Fprintln(w, "  line failed, and zero when every line succeeded.")
}

// runIngest 逐行处理标准输入，逐行输出 JSON 结果。返回进程退出码。
func runIngest(in io.Reader, out io.Writer) int {
	store := darksafe.NewMetricStore()
	r := bufio.NewReaderSize(in, 64*1024)
	enc := json.NewEncoder(out)
	enc.SetEscapeHTML(false)

	exitCode := 0
	lineNo := 0
	for {
		line, err := readIngestLine(r)
		if err == io.EOF {
			return exitCode
		}
		if err != nil {
			fmt.Fprintln(os.Stderr, "ingest: read error:", err)
			return 1
		}
		lineNo++
		if line.tooLong {
			// 超长行从开头到下一个行分隔符都属于同一条失败输入：
			// 内容已整体排空，不解析、不写入任何点、不执行任何查询。
			lineErr := &darksafe.LineError{
				Status: "error",
				Line:   lineNo,
				Error: fmt.Sprintf("line exceeds the %d-byte (64 MiB) single-line size limit",
					maxIngestLineBytes),
			}
			if err := enc.Encode(lineErr); err != nil {
				fmt.Fprintln(os.Stderr, "ingest: write error:", err)
				return 1
			}
			exitCode = 1
			continue
		}
		if len(strings.TrimSpace(line.text)) == 0 {
			continue // 空白行不产生结果，但已计入行号
		}
		result, lineErr := store.ProcessLine(line.text)
		if lineErr != nil {
			lineErr.Line = lineNo
			if err := enc.Encode(lineErr); err != nil {
				fmt.Fprintln(os.Stderr, "ingest: write error:", err)
				return 1
			}
			exitCode = 1
			continue
		}
		if err := enc.Encode(result); err != nil {
			fmt.Fprintln(os.Stderr, "ingest: write error:", err)
			return 1
		}
	}
}

// ingestLine 是读到的一行内容，不含结尾的 '\n' 分隔符（分隔符不计入行大小）。
// tooLong 为 true 时表示该行内容超过 maxIngestLineBytes，text 不保留其内容；
// 该行从开头到下一个 '\n' 的全部字节都已被排空，不会拆成多条输入。
type ingestLine struct {
	text    string
	tooLong bool
}

// readIngestLine 读取下一行输入。沿用 bufio.Scanner 的换行识别方式：
// 以 '\n' 分隔，结尾的 '\n' 不属于行内容（"foo\r\n" 的内容仍为 "foo\r"，
// 因此空白判定与现有行为一致）。行内容不超过上限时累积到 text；
// 一旦超过上限，停止累积并继续排空到下一个 '\n' 或输入结束，返回 tooLong。
// 输入直接结束且没有任何字节时返回 io.EOF；超长行在末尾无换行结束时
// 同样作为一条失败行返回，下一次调用才返回 io.EOF，不会丢失或重复。
// 除 io.EOF 外的非空 error 均为底层输入读取故障，调用方应终止处理。
func readIngestLine(r *bufio.Reader) (ingestLine, error) {
	var b strings.Builder
	size := 0
	tooLong := false
	for {
		chunk, err := r.ReadSlice('\n')
		if len(chunk) > 0 {
			if chunk[len(chunk)-1] == '\n' {
				chunk = chunk[:len(chunk)-1]
			}
			size += len(chunk)
			if size > maxIngestLineBytes {
				tooLong = true
				b = strings.Builder{} // 内容已注定失败，排空后续片段时不再保留此前累积
			}
			if !tooLong {
				b.Write(chunk)
			}
		}
		switch err {
		case nil:
			if tooLong {
				return ingestLine{tooLong: true}, nil
			}
			return ingestLine{text: b.String()}, nil
		case bufio.ErrBufferFull:
			// 行尚未结束且本次缓冲已耗尽，继续读取后续片段。
			continue
		case io.EOF:
			// 最后一行没有结尾换行；完全没有读到字节才表示输入结束，
			// 否则最后一行（含超长行）在本次返回，下次调用才得到 io.EOF。
			if size == 0 {
				return ingestLine{}, io.EOF
			}
			if tooLong {
				return ingestLine{tooLong: true}, nil
			}
			return ingestLine{text: b.String()}, nil
		default:
			return ingestLine{}, err
		}
	}
}

func runDemo() {
	subjects := []darksafe.Subject{
		{ID: "u-1001", Kind: "user", Roles: []string{"org/payments/ledger:read"}},
		{ID: "svc-batch", Kind: "service", Roles: []string{"owner"}},
		{ID: "u-1002", Kind: "user", Disabled: true},
	}
	resource := darksafe.Resource{ID: "ledger-main", Scope: "org/payments/ledger"}
	allowed := 0
	for _, subject := range subjects {
		decision := darksafe.Access(subject, resource, "read")
		if decision.Allowed {
			allowed++
		}
		fmt.Printf("subject=%s allowed=%v reason=%s\n", subject.ID, decision.Allowed, decision.Reason)
	}
	fmt.Printf("summary: %d of %d subjects allowed\n", allowed, len(subjects))
}

